(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-712":{scenario:{company:"Luc Bao Pharmaceuticals",supervisor:{name:"Hoàng Gia Linh",role:{vi:"Giám đốc Đăng ký thuốc",en:"Regulatory Affairs Director"}},ref_code:"VAR-2451",title:{vi:"Đúng phân loại. Đúng dữ liệu. Đúng hạn dùng.",en:"Right category. Real data. Justified shelf life."},brief:{vi:"Đây là tình huống đào tạo. Bạn chuẩn bị hồ sơ thay đổi VAR-2451 cho viên nén bao phim Lodivan 10 mg (sản phẩm mô phỏng) khi chuyển sản xuất thành phẩm sang nhà máy mới. Dữ liệu độ ổn định tại nhà máy mới: dài hạn 30°C/75%RH đủ 21 tháng, lão hóa cấp tốc 40°C/75%RH đủ 6 tháng, đều không có thay đổi đáng kể. Đối chiếu tờ khai thay đổi nháp với phiếu đánh giá đã duyệt, sửa phân loại thay đổi và hạn dùng đề xuất (tháng), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are preparing variation file VAR-2451 for Lodivan 10 mg film-coated tablets (a simulated product) after moving finished-product manufacturing to a new plant. Stability data from the new plant: long-term 30°C/75%RH for 21 months and accelerated 40°C/75%RH for 6 months, both with no significant change. Compare the draft variation form with the approved assessment, correct the variation category and the proposed shelf life (months), then write an evidence-based report."},reference_title:{vi:"Phiếu đánh giá thay đổi & tóm tắt độ ổn định",en:"Variation assessment & stability summary"},fields:[{id:"VAR_CLASS",label:{vi:"Phân loại thay đổi",en:"Variation category"},initial:"MiV-N",expected:"MaV",choices:["MaV","MiV-PA","MiV-N"],reference:"Phiếu đánh giá thay đổi",ref_value:{vi:"Thay đổi hoặc bổ sung cơ sở sản xuất thành phẩm: thay đổi lớn (MaV), phải được phê duyệt trước khi áp dụng",en:"Change or addition of a finished-product manufacturing site: major variation (MaV), prior approval required"},hint:{vi:"Đổi nơi sản xuất thành phẩm ảnh hưởng trực tiếp chất lượng, không phải thay đổi hành chính chỉ cần thông báo.",en:"Moving finished-product manufacturing directly affects quality; it is not an administrative notification."}},{id:"SHELF_LIFE",label:{vi:"Hạn dùng đề xuất (tháng)",en:"Proposed shelf life (months)"},initial:"36",expected:"33",reference:"Tóm tắt dữ liệu độ ổn định",ref_value:{vi:"Dài hạn 30°C/75%RH: 21 tháng, không thay đổi đáng kể; cấp tốc: 6 tháng, không thay đổi đáng kể",en:"Long-term 30°C/75%RH: 21 months, no significant change; accelerated: 6 months, no significant change"},hint:{vi:"Ngoại suy hạn dùng bị giới hạn bởi hai điều kiện, lấy giá trị nhỏ hơn.",en:"Shelf-life extrapolation is capped by two limits; take the smaller one."}}],sop32:{vi:"Theo nguyên tắc ICH Q1E áp dụng trong bài: khi dữ liệu ít thay đổi, hạn dùng đề xuất tối đa = giá trị nhỏ hơn giữa (2 x thời gian dữ liệu dài hạn) và (thời gian dữ liệu dài hạn + 12 tháng).",en:"Per the ICH Q1E principle used here: when data show little change, the maximum proposed shelf life = the smaller of (2 x long-term data period) and (long-term data period + 12 months)."},context:{label:"RIM / VAR-2451",metrics:[{label:{vi:"Dữ liệu dài hạn (tháng)",en:"Long-term data (months)"},value:"21"},{label:{vi:"Dữ liệu cấp tốc (tháng)",en:"Accelerated data (months)"},value:"6"},{label:{vi:"Vùng khí hậu",en:"Climatic zone"},value:"IVb"},{label:{vi:"Hạn dùng bao bì cũ (tháng)",en:"Old pack shelf life (months)"},value:"36"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Ghi 36 tháng cho khớp 200.000 hộp đã in sẵn. Trong báo cáo độ ổn định cứ ghi là đã có dữ liệu 24 tháng, nộp trước rồi bổ sung sau, chẳng ai soát kỹ đâu.”",en:"The sales director messages you: “Put 36 months to match the 200,000 cartons already printed. In the stability report just say we have 24 months of data, file now and add data later, nobody checks closely.”"},options:{safe:{vi:"Từ chối khai sai dữ liệu, nộp hạn dùng 30 tháng kèm cam kết tiếp tục theo dõi độ ổn định, báo Giám đốc Đăng ký và QA, xử lý bao bì đã in qua quy trình kiểm soát thay đổi.",en:"Refuse to misstate data, file a 30-month shelf life with an ongoing stability commitment, inform the RA Director and QA, and handle printed cartons through change control."},shortcut:{vi:"Ghi 36 tháng và dữ liệu 24 tháng để kịp nộp, sau này bổ sung số liệu thật.",en:"Enter 36 months and 24 months of data to file on time and add the real data later."},wait:{vi:"Dừng soạn hồ sơ và chờ kinh doanh với nhà máy tự thống nhất hạn dùng.",en:"Stop drafting and wait for Sales and the plant to agree on the shelf life."}},questions:{vi:["Vì sao thay đổi này thuộc MaV và hạn dùng tối đa chỉ là 30 tháng? Dẫn chứng từ phiếu đánh giá và dữ liệu độ ổn định.","Bạn xử lý số bao bì đã in hạn dùng 36 tháng và lộ trình xin kéo dài hạn dùng thế nào cho hợp lệ?"],en:["Why is this an MaV and why is the shelf life capped at 30 months? Cite the assessment and the stability data.","How do you handle cartons printed with 36 months and plan a lawful shelf-life extension?"]},hints:{vi:["Xác định thay đổi tác động đến chất lượng thành phẩm hay chỉ là thông tin hành chính.","Tính cả hai giới hạn ngoại suy ở SOP mục 3.2 rồi chọn giá trị nhỏ hơn.","Đọc lại SOP mục 4.2: không bao giờ khai dữ liệu chưa có; mọi áp lực phải báo cáo người có thẩm quyền."],en:["Decide whether the change affects finished-product quality or is only administrative.","Compute both extrapolation limits in SOP 3.2 and take the smaller one.","Re-read SOP 4.2: never declare data you do not have; escalate any pressure to the responsible person."]}},learning:{summary:{vi:"Chuyên viên đăng ký thuốc và trang thiết bị y tế (RA) chuẩn bị, nộp và theo dõi hồ sơ cấp phép lưu hành, gia hạn và thay đổi sản phẩm với cơ quan quản lý. Người làm nghề hiểu cấu trúc hồ sơ ACTD/CTD, yêu cầu chất lượng, an toàn, hiệu quả, phân loại thay đổi và phân loại rủi ro thiết bị. Giá trị cốt lõi là đưa sản phẩm ra thị trường đúng hạn mà vẫn trung thực tuyệt đối về dữ liệu.",en:"A regulatory affairs (RA) specialist for medicines and medical devices prepares, submits and tracks marketing authorizations, renewals and variations with the regulator. The role requires knowing the ACTD/CTD dossier structure, quality, safety and efficacy requirements, variation categories and device risk classes. Its core value is bringing products to market on time with absolute data integrity."},responsibilities:{vi:["Lập hồ sơ đăng ký lưu hành mới, gia hạn và thay đổi theo định dạng ACTD/CTD.","Phân loại thay đổi, xác định tài liệu cần nộp và thời điểm được phép áp dụng.","Rà soát dữ liệu chất lượng, độ ổn định, tương đương sinh học và nhãn, tờ hướng dẫn sử dụng.","Phân loại mức độ rủi ro trang thiết bị y tế và chuẩn bị hồ sơ công bố hoặc đăng ký lưu hành.","Theo dõi công văn, trả lời yêu cầu bổ sung và quản lý hiệu lực giấy phép trên hệ thống."],en:["Compile new, renewal and variation dossiers in ACTD/CTD format.","Classify variations, define required documents and when the change may be implemented.","Review quality, stability, bioequivalence data and labels and package inserts.","Classify medical device risk and prepare declaration or registration files.","Track official letters, answer deficiency requests and manage licence validity in the system."]},competencies:[{name:{vi:"Pháp quy dược & thiết bị",en:"Drug & device regulation"},desc:{vi:"Nắm quy định đăng ký thuốc, trang thiết bị y tế và hướng dẫn ASEAN, ICH liên quan.",en:"Know drug and device registration rules and the related ASEAN and ICH guidance."}},{name:{vi:"Biên soạn hồ sơ kỹ thuật",en:"Technical dossier writing"},desc:{vi:"Tổ chức hồ sơ ACTD/CTD mạch lạc, nhất quán giữa các phần chất lượng, lâm sàng và nhãn.",en:"Build coherent ACTD/CTD dossiers that stay consistent across quality, clinical and labelling parts."}},{name:{vi:"Đánh giá dữ liệu khoa học",en:"Scientific data review"},desc:{vi:"Đọc hiểu dữ liệu độ ổn định, thẩm định quy trình và tiêu chuẩn chất lượng để phát hiện lỗ hổng.",en:"Read stability, validation and specification data to spot gaps."}},{name:{vi:"Quản lý tiến độ",en:"Timeline management"},desc:{vi:"Lập kế hoạch nộp, theo dõi thời hạn trả lời và hiệu lực giấy phép, tránh gián đoạn cung ứng.",en:"Plan submissions, track response deadlines and licence expiry to avoid supply gaps."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Chỉ khai dữ liệu có thật, đầy đủ và truy xuất được; từ chối mọi yêu cầu chỉnh sửa sai sự thật.",en:"Declare only real, complete, traceable data and refuse any request to misstate it."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 về đăng ký lưu hành thuốc và nguyên liệu làm thuốc.","Thông tư 08/2022/TT-BYT quy định việc đăng ký lưu hành thuốc, nguyên liệu làm thuốc.","Nghị định 98/2021/NĐ-CP về quản lý trang thiết bị y tế, phân loại rủi ro A, B, C, D.","Hồ sơ kỹ thuật chung ASEAN (ACTD) và định dạng CTD của ICH.","ICH Q1A(R2), Q1E về nghiên cứu độ ổn định; điều kiện vùng khí hậu IVb 30°C/75%RH.","Hướng dẫn thay đổi ASEAN: MaV, MiV-PA, MiV-N."],en:["Pharmacy Law No. 105/2016/QH13 on marketing authorization of medicines and starting materials.","Circular 08/2022/TT-BYT on registration of medicines and pharmaceutical starting materials.","Decree 98/2021/ND-CP on medical device management with risk classes A, B, C and D.","The ASEAN Common Technical Dossier (ACTD) and the ICH CTD format.","ICH Q1A(R2) and Q1E on stability testing; climatic zone IVb at 30°C/75%RH.","The ASEAN variation guideline: MaV, MiV-PA and MiV-N."]},tools:["Cổng dịch vụ công trực tuyến ngành y tế","Hệ thống quản lý thông tin đăng ký (RIM)","Phần mềm biên soạn hồ sơ CTD/ACTD","Phần mềm phân tích dữ liệu độ ổn định","Microsoft Excel"],kpis:{vi:["Tỷ lệ hồ sơ được chấp thuận không phải bổ sung lần hai.","Số sản phẩm gián đoạn lưu hành do hết hạn giấy phép (mục tiêu bằng 0).","Thời gian trung bình trả lời công văn yêu cầu bổ sung.","Số phát hiện về tính toàn vẹn dữ liệu khi thanh tra, đánh giá (mục tiêu bằng 0)."],en:["Share of dossiers approved without a second deficiency round.","Products disrupted by expired licences (target zero).","Average time to answer deficiency letters.","Data integrity findings in inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra công văn mới, hạn trả lời và lịch hết hiệu lực giấy phép.",en:"Check new official letters, response deadlines and licence expiry dates."},{time:"09:30",vi:"Họp với QA và nhà máy về kế hoạch thay đổi, phân loại và tài liệu cần nộp.",en:"Meet QA and the plant on planned changes, their category and required documents."},{time:"11:00",vi:"Rà soát báo cáo độ ổn định, tính hạn dùng đề xuất có căn cứ.",en:"Review stability reports and justify the proposed shelf life."},{time:"14:00",vi:"Biên soạn, kiểm tra chéo hồ sơ ACTD và bản dịch nhãn, tờ hướng dẫn sử dụng.",en:"Compile and cross-check the ACTD file and translated labels and inserts."},{time:"16:30",vi:"Nộp hồ sơ trực tuyến, cập nhật hệ thống RIM và báo cáo tiến độ.",en:"Submit online, update the RIM system and report progress."}],mistakes:{vi:["Xếp thay đổi cơ sở sản xuất vào loại chỉ cần thông báo và áp dụng trước khi được duyệt.","Nhân đôi thời gian dữ liệu dài hạn mà quên giới hạn cộng tối đa 12 tháng.","Khai dữ liệu độ ổn định chưa có hoặc bỏ bớt kết quả không đạt để kịp hạn nộp."],en:["Treating a manufacturing site change as a notification and implementing it before approval.","Doubling the long-term period while forgetting the 12-month cap.","Declaring stability data that does not exist or dropping failing results to meet a deadline."]},career:[{vi:"Trợ lý đăng ký thuốc",en:"Regulatory affairs assistant"},{vi:"Chuyên viên đăng ký thuốc & trang thiết bị y tế",en:"Regulatory affairs specialist"},{vi:"Trưởng nhóm đăng ký / Chuyên gia pháp quy cấp cao",en:"RA team lead / Senior regulatory expert"},{vi:"Giám đốc Đăng ký & Pháp quy khu vực",en:"Regional Head of Regulatory Affairs"}],glossary:[{term:"ACTD",vi:"Hồ sơ kỹ thuật chung ASEAN gồm các phần hành chính, chất lượng, tiền lâm sàng và lâm sàng.",en:"ASEAN Common Technical Dossier with administrative, quality, nonclinical and clinical parts."},{term:"MaV",vi:"Thay đổi lớn: ảnh hưởng đáng kể đến chất lượng, an toàn, hiệu quả, cần phê duyệt trước.",en:"Major variation with a significant impact on quality, safety or efficacy; prior approval needed."},{term:"MiV-N",vi:"Thay đổi nhỏ chỉ cần thông báo, thường là thông tin hành chính không ảnh hưởng chất lượng.",en:"Minor variation by notification, usually administrative with no quality impact."},{term:"Shelf life",vi:"Hạn dùng: khoảng thời gian thuốc giữ nguyên tiêu chuẩn chất lượng trong điều kiện bảo quản ghi trên nhãn.",en:"The period a medicine stays within specification under the labelled storage conditions."},{term:"Zone IVb",vi:"Vùng khí hậu nóng, rất ẩm; điều kiện nghiên cứu độ ổn định dài hạn 30°C/75%RH.",en:"Hot, very humid climatic zone with long-term stability testing at 30°C/75%RH."}],quiz:[{q:{vi:"Dữ liệu dài hạn 24 tháng ít thay đổi, cấp tốc đạt. Theo nguyên tắc ICH Q1E, hạn dùng đề xuất tối đa là bao nhiêu?",en:"Long-term data cover 24 months with little change and accelerated data pass. Per ICH Q1E, what is the maximum proposed shelf life?"},options:{vi:["24 tháng","48 tháng","60 tháng","36 tháng"],en:["24 months","48 months","60 months","36 months"]},answer:3,explain:{vi:"Nhỏ hơn giữa 2 x 24 = 48 và 24 + 12 = 36, nên tối đa 36 tháng.",en:"The smaller of 2 x 24 = 48 and 24 + 12 = 36, so 36 months at most."}},{q:{vi:"Trang thiết bị y tế tại Việt Nam được phân loại rủi ro như thế nào?",en:"How are medical devices risk-classified in Vietnam?"},options:{vi:["3 loại I, II, III","4 loại A, B, C, D với D rủi ro cao nhất","2 loại có và không xâm lấn","Theo giá trị nhập khẩu"],en:["3 classes I, II, III","4 classes A, B, C, D with D the highest risk","2 classes, invasive or not","By import value"]},answer:1,explain:{vi:"Nghị định 98/2021/NĐ-CP chia trang thiết bị y tế thành loại A, B, C, D theo mức độ rủi ro tăng dần.",en:"Decree 98/2021/ND-CP groups devices into classes A, B, C and D by increasing risk."}},{q:{vi:"Cấp trên đề nghị ghi là đã có dữ liệu 24 tháng dù mới có 21 tháng. Bạn làm gì?",en:"Your manager asks you to state 24 months of data when only 21 exist. What do you do?"},options:{vi:["Từ chối, nộp đúng dữ liệu và báo cáo người có thẩm quyền","Ghi theo yêu cầu rồi bổ sung sau","Ghi mập mờ “khoảng 2 năm”","Hoãn nộp vô thời hạn"],en:["Refuse, file the true data and escalate","Comply and update later","Write a vague “about 2 years”","Postpone filing indefinitely"]},answer:0,explain:{vi:"Khai dữ liệu không có thật là vi phạm tính toàn vẹn dữ liệu và có thể bị thu hồi giấy phép.",en:"Declaring non-existent data breaches data integrity and can lead to licence withdrawal."}},{q:{vi:"Điều kiện nghiên cứu độ ổn định dài hạn cho vùng khí hậu IVb là gì?",en:"What are the long-term stability conditions for climatic zone IVb?"},options:{vi:["25°C/60%RH","40°C/75%RH","30°C/75%RH","5°C ± 3°C"],en:["25°C/60%RH","40°C/75%RH","30°C/75%RH","5°C ± 3°C"]},answer:2,explain:{vi:"Vùng IVb (nóng, rất ẩm) như Việt Nam dùng 30°C/75%RH; 40°C/75%RH là điều kiện lão hóa cấp tốc.",en:"Zone IVb (hot, very humid) such as Vietnam uses 30°C/75%RH; 40°C/75%RH is the accelerated condition."}}],tools_en:["Health sector online public service portal","Regulatory information management (RIM) system","CTD/ACTD dossier authoring software","Stability data analysis software","Microsoft Excel"]}}})})(window.KKR);
